class MagixToast{static success(s){this.show(s,"success")}static error(s){this.show(s,"error")}static warning(s){this.show(s,"warning")}static info(s){this.show(s,"info")}static show(s,e="info"){const i=document.getElementById("magix-toast-container");if(!i){console.warn("MagixToast: Le conteneur #magix-toast-container est introuvable.");return}const o={success:{bg:"text-bg-success",icon:"bi-check-circle"},error:{bg:"text-bg-danger",icon:"bi-exclamation-octagon"},warning:{bg:"text-bg-warning",icon:"bi-exclamation-triangle"},info:{bg:"text-bg-info",icon:"bi-info-circle"}},n=o[e]||o.info,t=document.createElement("div");t.className=`toast align-items-center border-0 mb-3 shadow-lg ${n.bg}`,t.setAttribute("role","alert"),t.setAttribute("aria-live","assertive"),t.setAttribute("aria-atomic","true");const a=e==="success"||e==="error"?"btn-close-white":"";t.innerHTML=`
            <div class="d-flex">
                <div class="toast-body d-flex align-items-center">
                    <i class="bi ${n.icon} fs-5 me-3"></i>
                    <span class="fw-medium"></span>
                </div>
                <button type="button" class="btn-close ${a} me-2 m-auto" data-bs-dismiss="toast" aria-label="Fermer"></button>
            </div>
        `,t.querySelector(".fw-medium").textContent=String(s??""),i.appendChild(t),new bootstrap.Toast(t,{delay:4e3}).show(),t.addEventListener("hidden.bs.toast",()=>{t.remove()})}}
